#!/usr/bin/env python3
# Some portions generated by Codex. Isolated measured-artifact selection.
from pathlib import Path
p=Path(__file__).resolve().parent
s=(p.parent/'workbench-e2e/run.py').read_text()
s=s.replace('a=p.parse_args()', "p.add_argument('--hot-split',action='store_true');p.add_argument('--jit',action='store_true');a=p.parse_args()")
s=s.replace("libs=sorted((d/'runtime/BOOT-INF/lib').glob('*.jar'))", "if a.hot_split:lmdb=root/'experiments/overlay/memo-hot-split/candidate-classes'\nlibs=sorted((d/'runtime/BOOT-INF/lib').glob('*.jar'))")
s=s.replace("cmd=[str(java)", "flags['rdf4j.lmdb.nativeValueMemo.entryMetadata']='false'\ncmd=[str(java)")
s=s.replace("if a.profile:\n cmd[1:1]", "if a.jit:\n cmd[1:1]=['-XX:+UnlockDiagnosticVMOptions','-XX:+LogCompilation','-XX:LogFile='+str(d/(a.name+'-compilation.xml'))]\nif a.profile:\n cmd[1:1]")
s=s.replace("'-XX:StartFlightRecording=settings=profile,dumponexit=true,filename='+str(d/(a.name+'.jfr'))", "'-XX:StartFlightRecording=settings='+str(root/'experiments/overlay/memo-diagnosis/compilation.jfc')+',dumponexit=true,filename='+str(d/(a.name+'.jfr'))")
s=s.replace("result['witnessesPassed']=True;", "if a.hot_split:\n  assert after['org.eclipse.rdf4j.sail.lmdb.LmdbStore'].endswith('/memo-hot-split/candidate-classes/'),after\n  assert after['memoEntryMetadataEnabled']==False,after\n result['witnessesPassed']=True;")
(p/'run-split.py').write_text(s)
